Here is the Python function using Dijkstra's algorithm to find the shortest path. It includes checks for negative edge weights and handles cases where no path exists or the start and end nodes are the same.

```python
import heapq


def shortest_path(edges, start, end):
    # Check for negative weights
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Edge weights cannot be negative.")

    # If start and end are the same
    if start == end:
        return (0, [start])

    # Build the adjacency list
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
      # Ensure end node (and any isolated nodes) exist in the graph
            graph[v] = []
        graph[u].append((v, w))

    # Priority queue stores: (current_distance, current_node, path_so_far)
    pq = [(0, start, [start])]

    # Keep track of the shortest distance to each node to avoid redundant work
    min_distances = {start: 0}

    while pq:
        current_distance, current_node, path = heapq.heappop(pq)

        # If we reached the destination, return the result
        if current_node == end:
            return (current_distance, path)

        # If we found a longer path to the current node than already recorded, skip
        if current_distance > min_distances.get(current_node, float("inf")):
            continue

        # Explore neighbors
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                # If this path is shorter than any previously found path to the neighbor
                if distance < min_distances.get(neighbor, float("inf")):
                    min_distances[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor, path + [neighbor]))

    # If the priority queue is exhausted and we haven't reached 'end'
    return (None, None)
```

### Example Usage:

```python
edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
print(shortest_path(edges, "A", "C"))
# Output: (3, ['A', 'B', 'C'])

# No path exists:
print(shortest_path(edges, "C", "A"))
# Output: (None, None)

# Negative weight raises ValueError:
try:
    shortest_path([("A", "B", -1)], "A", "B")
except ValueError as e:
    print(e)
# Output: Edge weights cannot be negative.
```

